insert into public.questions (question_id,paper_id,question_number,question_type,question_points,question_text,option_a,option_b,option_c,option_d,option_e,subject_primary,subsubject_primary,subject_secondary,chapter,topic_primary,topic_secondary,law_refs,tags,source_page_start,source_page_end,extraction_status,review_status,notes,is_published) values
('107-3301-018','107-3301',18,'single_choice',2,'甲向乙借款1,000 萬元，清償期屆至，甲無力清償，乃跟乙約定以其坐落於新店的價值約1,000 萬元 之房屋移轉登記給乙，以代替原定債務之清償，下列敘述，何者正確？','代物清償一經甲、乙合意，舊債務即消滅','甲、乙之約定，屬於間接給付','在甲移轉登記不動產給乙前，不成立代物清償','在甲移轉登記不動產給乙前，甲、乙間之約定無效',null,'民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('107-3301-019','107-3301',19,'single_choice',2,'甲欲出售A 車予乙，甲依約定將該車交付予乙試用1 週，試用後始由乙決定是否承認買賣，惟乙於 試用期間內，拆卸該車之音響設備。有關本案之法律效果，下列敘述，何者正確？','雖乙拆卸音響設備，惟乙尚未為承認之表示，所以甲與乙間之買賣契約尚未生效','若乙歸還音響設備及A 車，則甲與乙間不發生買賣關係','甲與乙間之買賣契約生效，並且若該音響設備有瑕疵，甲應負物之瑕疵擔保責任','甲與乙間之買賣契約生效，惟若該音響設備有瑕疵，甲不負物之瑕疵擔保責任',null,'民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('107-3301-020','107-3301',20,'single_choice',2,'甲承租乙所有之A 地建築房屋，租期50 年，雙方簽訂一書面契約，俟房屋落成後，甲竟將該屋出賣 予丙，並為所有權之移轉。其法律效果，下列敘述，何者正確？','乙得請求丙拆屋還地，因乙、丙間無租賃關係','乙依民法規定得終止與甲間之租賃契約，因甲將新建之房屋讓與丙','丙得解除與甲間之房屋買賣契約，因甲無A 地之所有權','乙得向丙請求給付租金，因乙、丙間依法有租賃關係',null,'民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('107-3301-021','107-3301',21,'single_choice',2,'甲、乙訂立承攬契約，約定由乙於甲所有之A 地興建旅館。惟A 地長期無人使用，故甲在A 地堆放 許多雜物，且附近鄰居們也將車子停在A 地，致乙無法動工，乙便央請甲處理A 地上之雜物及車子， 以供施工之用。下列敘述，何者正確？','乙因不能施工而造成之金錢損失，得對甲及停車之鄰居請求侵權行為損害賠償','甲在法律上並無任何義務協助乙處理A 地上之雜物及車子','乙定相當期限催告甲處理仍無結果後，乙得逕向甲請求損害賠償','乙定相當期限催告甲處理仍無結果後，乙得解除契約，並得請求賠償因契約解除而生之損害',null,'民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('107-3301-022','107-3301',22,'single_choice',2,'甲委託乙管理其房屋之出租事宜，其中A 戶屋頂漏水，乙緊急找丙修繕，並將屋頂重新油漆。B 戶 經丁重新裝潢後，乙前往驗收，並準備拍照刊登出租廣告，未料洗手台破裂致乙受傷，須緊急送醫 治療。後經勘驗認定為丁裝潢時施工疏失，導致洗手台於數天後破裂。下列敘述，何者錯誤？','乙處理屋頂漏水事宜，所支出之必要費用與有益費用，依民法第546 條規定均得向甲請求返還','乙得依侵權行為之規定向丁請求賠償損害','乙、丁之間如有契約關係，乙尚得依債務不履行之規定向丁請求賠償損害','洗手台破裂雖非甲所造成，乙仍得向甲請求損害賠償',null,'民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('107-3301-023','107-3301',23,'single_choice',2,'下列何種情形不屬於隱名合夥之終止原因？','當初所約定之目的事業已完成','隱名合夥人死亡','出名營業人受監護宣告','隱名合夥人受破產之宣告',null,'民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('107-3301-024','107-3301',24,'single_choice',2,'下列何者，不得作為和解之對象？','婚姻關係是否成立','特定身分所生的財產關係','已經法院確定之法律關係，當事人實際上仍有爭執','無體財產權關係',null,'民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('107-3301-025','107-3301',25,'single_choice',2,'甲受好友乙之委託，擔保乙對A 銀行連續發生之債務，負未定有期限之保證責任，但因近來經濟不 景氣，乙常有遲延繳息之情形，下列敘述，何者錯誤？','甲得隨時通知A 銀行終止保證契約','甲得於主債務屆清償期後，定1 個月以上之相當期間，催告A 銀行於期限內向乙為審判上之請求','甲得向乙請求除去其保證責任','甲通知A 銀行終止保證契約時，即對所有債務不負保證責任',null,'民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('107-3301-026','107-3301',26,'single_choice',2,'甲為慶祝乙通過律師高考，贈與乙A 地，甲與乙間因此成立一贈與契約，惟未辦理公證。嗣後，甲 將A 地之所有權移轉予乙，下列敘述，何者正確？','甲得隨時撤銷此一贈與契約','若A 地上業已設定普通抵押權，而甲於締結贈與契約時，故意不將此一情事告知乙，甲仍不負權 利瑕疵擔保責任','若乙有故意傷害甲身體之行為，甲仍不得撤銷此一贈與契約','若乙有故意傷害甲身體之行為，而乙又已死亡者，甲即不得對乙之繼承人撤銷此一贈與契約',null,'民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('107-3301-027','107-3301',27,'single_choice',2,'甲向乙購買A 車一輛，價金50 萬元，約定於清償期屆至時，如甲無力支付，則乙將此價金50 萬元 轉為借款，下列敘述，何者正確？','甲、乙之約定為消費借貸預約','甲、乙之約定為有償使用借貸','甲、乙之約定為準消費借貸','甲、乙之約定為無償使用借貸',null,'民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('107-3301-028','107-3301',28,'single_choice',2,'甲有A 地，因地政機關登記錯誤為乙之名義，詎乙將該地設定普通抵押權與善意之丙，據以向丙借 款。下列敘述，何者正確？','因地政機關登記之錯誤，乙取得A 地之所有權','乙將A 地設定普通抵押權與丙的行為，係屬有權處分','甲不得請求丙塗銷普通抵押權之登記','甲對丙有償還借款之義務',null,'民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('107-3301-029','107-3301',29,'single_choice',2,'甲、乙之土地相鄰，甲地之家庭用水偶而有排泄至乙地之必要。因乙將其土地填高，欲妨礙甲地用 水之排泄。下列敘述，何者錯誤？','甲、乙之相鄰關係類似不動產役權，甲取得獨立之限制物權，得對乙提起確認排水不動產役權存 在之訴','甲、乙此種相鄰關係，係因法律規定而生，乃土地上之法定負擔','甲、乙此種排水相鄰關係，不得與土地所有權分離而任意拋棄','有關相鄰關係之法律規定乃強行規定，當事人不得作相反之約定',null,'民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('107-3301-030','107-3301',30,'single_choice',2,'關於共有物之裁判分割，下列敘述，何者正確？','法院命以變賣共有物為分割時，除買受人為共有人外，共有人有依相同條件優先承買之權，有二 人以上願優先承買者，共同承買之','共有人部分相同之相鄰數不動產，各該不動產均具應有部分之共有人全體同意者，始得請求合併 分割','共有人向法院請求分割共有物時，由同意分割的共有人全體共同起訴，並以反對分割之其他共有 人全體為共同被告','法院之分割應斟酌共有物之性質及價格，依當事人主張的方法分配',null,'民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('107-3301-031','107-3301',31,'single_choice',2,'甲、乙共有土地一宗，面積200 坪，應有部分各為二分之一。甲、乙口頭同意將共有土地依東西方 向，平均分割為100 坪，甲取得東邊之100 坪，乙取得西邊之100 坪，並經測量分別為測量圖之A、 B 部分。嗣後，甲認為應依南北方向平分，方為公平，故不願履行。下列敘述，何者正確？','乙得以甲為被告，訴請法院判決：甲、乙應協同辦理各取得如測量圖所示A、B 部分之分割登記','乙得以甲為被告，訴請法院判決：甲應協同乙辦理乙取得如測量圖所示B 部分之分割登記','乙得以甲為被告，訴請法院判決分割共有土地，並應依測量圖所示方法分割','甲得以乙為被告，訴請法院判決分割共有土地，並應依南北方向平分',null,'民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('107-3301-032','107-3301',32,'single_choice',2,'甲、乙、丙共有A 地，各有應有部分三分之一。三人約定：將A 地分為三區，分別由甲、乙、丙管 理A1、A2、A3。嗣後，甲將其應有部分設定普通抵押權給丁，而共有物分割後，由甲、乙、丙分 別取得A1、A2、A3 之所有權。下列敘述，何者正確？','甲設定抵押權給丁時，至少應得另一位共有人之同意','丁如經共有人告知共有物分割訴訟而未參加，其抵押權於分割後移存於A1','各共有人對於其他共有人因分割而取得之物，不得互相主張買受人之權利','甲如因分割應補償金錢給丙，丙就其補償金額，對於A1 有抵押權；丁移存於A1 之抵押權次序優先',null,'民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('107-3301-033','107-3301',33,'single_choice',2,'甲承租乙之土地後，有使用鄰地丙土地之必要，欲設定不動產役權。下列敘述，何者正確？','甲未經乙之同意，不得任意為乙之土地使用需要設定不動產役權','甲經乙之同意設定之不動產役權，於甲、乙間租約到期後，該不動產役權即為消滅','甲未得乙之同意所設定之不動產役權，縱經登記，亦不發生效力','甲未得乙之同意設定之不動產役權，不得在乙之土地上為登記',null,'民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('107-3301-034','107-3301',34,'single_choice',2,'甲名下有A 地及B 屋，甲將A 地與B 屋設定普通抵押權予乙，作為向乙借款之擔保。甲嗣後未依約 清償債務，乙即聲請法院查封拍賣A 地與B 屋。法院於查封時發現甲在A 地種植果樹，且其B 屋、 連同抵押權設定前所增建之不具獨立性的C 廚房已出租予丁使用，乙遂通知丁自查封後應對其繳交 租金。兩個月後，B 屋因地震倒塌，黏貼在屋簷上之D 交趾陶雖掉落於地，但拆取後竟然無損。下 列何者，非為乙之抵押權效力所及？','B 屋查封後之租金','D 交趾陶','A 地查封前自果樹掉落之果實','增建之C 廚房',null,'民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('107-3301-035','107-3301',35,'single_choice',2,'甲為擔保乙的債權，將其房屋設定普通抵押權與乙，下列敘述，何者正確？','抵押權設定後的房屋租金，應為抵押權效力所及','房屋被丙縱火燒燬一部分之後，抵押權全部均歸於消滅','房屋被丙縱火燒燬後，乙得就甲對丙的損害賠償金額，主張優先受清償','抵押物滅失後，如有殘餘物，乙不得請求占有',null,'民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('107-3301-036','107-3301',36,'single_choice',2,'出質人甲為舉辦活動需要，說服質權人乙，將甲所提供為擔保丙之債務之質物暫時交付，活動結束 後甲尚未返還該物，乙已私下說服甲之受僱人丁交回該物。下列敘述，何者正確？','乙之動產質權不受影響','乙之動產質權雖消滅，但又再回復','丙得撤銷乙之動產質權','乙就該物為無權占有',null,'民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('107-3301-037','107-3301',37,'single_choice',2,'甲與乙訂立租賃契約，甲將承租房屋一棟之一間出租於乙，甲依約將該房屋之一間交付於乙使用。 下列敘述，何者正確？','房屋一間是房屋之一部分，非獨立物，故不得為占有移轉之標的物','甲將房屋之一間交付乙占有，甲對該房屋一間之占有已消滅','甲對該房屋一間與乙之占有關係，是為自己創設間接占有','甲對該房屋一間與乙之占有關係，是為自己創設占有輔助關係',null,'民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('107-3301-038','107-3301',38,'single_choice',2,'關於被詐欺而結婚，下列敘述，何者錯誤？','撤銷權人得於發現詐欺後，6 個月內向法院請求撤銷之，且被詐欺而為意思表示後，雖已經過10 年，仍得撤銷之','婚姻因被詐欺而撤銷，若因而受有財產上之損害者，得向有過失之他方請求損害賠償，但以請求 者無過失為限','婚姻因被詐欺而撤銷，準用判決離婚關於贍養費之規定','婚姻因被詐欺而撤銷，其撤銷之效力不溯及既往',null,'民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('107-3301-039','107-3301',39,'single_choice',2,'甲是乙的媽媽的舅舅的女兒的兒子，請問甲、乙之間是什麼親系親等？','旁系姻親五親等','旁系姻親六親等','旁系血親五親等','旁系血親六親等',null,'民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('107-3301-040','107-3301',40,'single_choice',2,'下列關於「處分」問題之敘述，何者錯誤？','監護人代理受監護人處分不動產，非經法院許可，不生效力','父母對於未成年子女之特有財產，非為子女之利益，不得處分','夫妻選用共同財產制者，夫妻之一方，對於自己之特有財產為處分時，應得他方之同意','受輔助宣告之人為汽車之處分或設定負擔，應經輔助人之同意',null,'民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('107-3301-041','107-3301',41,'single_choice',2,'法定財產制中，有關夫妻財產所有權之歸屬，下列敘述，何者正確？','夫或妻之財產不論屬於婚前或婚後財產均由夫妻各自所有','夫或妻之財產不能證明為婚前或婚後財產者視為婚後財產','夫或妻之財產不能證明為夫或妻所有之財產視為共有財產','夫或妻婚前財產於婚姻關係存續中所生之孳息視為婚前財產',null,'民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('107-3301-042','107-3301',42,'single_choice',2,'甲男與乙女為夫妻，後來經法院判決離婚確定，甲遂與丙女結婚，惟甲、乙上開離婚判決在甲、丙 結婚後經再審判決廢棄。下列敘述，何者正確？','若僅丙善意且無過失信賴甲、乙之離婚確定判決而與甲結婚，甲、乙之婚姻與甲、丙之婚姻均有 效存在','若甲與丙因善意且無過失信賴甲、乙之離婚確定判決而結婚，甲、乙之婚姻與甲、丙之婚姻均有 效存在','若僅丙善意且無過失信賴甲、乙之離婚確定判決而與甲結婚，甲、丙之婚姻有效，甲、乙之婚姻 自甲、乙離婚判決確定之日起，視為消滅','若甲與丙因善意且無過失信賴甲、乙之離婚確定判決而結婚，甲、丙之婚姻有效，甲、乙之婚姻 自甲、丙婚姻成立之日起，視為消滅',null,'民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('107-3301-043','107-3301',43,'single_choice',2,'甲男於民國102 年1 月1 日死亡，下列何種行為於甲男死後所為，仍得發生法律上之效力？','甲男之父母為甲及其生前之女友乙舉行冥婚','甲男之非婚生子女乙向甲之繼承人提起認領之訴','甲男之妻乙為甲立繼，收養丙男為甲之養子','甲男生前被乙收養，甲死後，養父乙聲請法院許可終止收養',null,'民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('107-3301-044','107-3301',44,'single_choice',2,'甲、乙結婚生子戊，與甲之父母丙、丁同住，某日甲、乙兩人開車赴宴同時發生車禍，意外雙亡。 甲、乙死亡時，戊10 歲，甲、乙生前並未指定監護人。下列敘述，何者正確？','甲、乙死亡後，應由與同住之祖父母丙、丁為戊之監護人','丙、丁為監護人之後，開始為戊管理財產時，應會同親屬會議所指定之人，開具財產清冊','若丙、丁為戊執行財產上之監護有過失時，並造成戊受有損害，由於丙、丁為戊之祖父母，所以 對戊不用負損害賠償責任','由於丙、丁為戊之祖父母，所以丙、丁不得針對監護事務請求報酬',null,'民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('107-3301-045','107-3301',45,'single_choice',2,'甲、乙兩人結婚時皆白手起家，結婚時兩人皆無任何財產。結婚前後兩人從未約定夫妻財產制。結 婚10 年後甲死亡，當時甲名下藉由婚後的勞力賺取，累積有170 萬元財產，乙名下則藉由婚後的勞 力賺取累積有30 萬元財產。兩人並育有子女A、B、C，甲死亡時其父母丙、丁皆健在。甲遺留下之 170 萬元如何分配？','乙、A、B、C 各42.5 萬元','乙70 萬元，A、B、C、丙、丁各20 萬元','乙95 萬元，A、B、C 各25 萬元','乙85 萬元，丙、丁各42.5 萬元',null,'民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('107-3301-046','107-3301',46,'single_choice',2,'下列有關概括繼承有限責任之敘述，何者錯誤？','債權人得於知悉繼承開始時起3 個月內命繼承人提出遺產清冊','繼承人對於繼承開始時尚未屆清償期之債權，仍應視為已到期之債權而加以清償','被繼承人於繼承開始前2 年內，對於繼承人因結婚所為之財產贈與，於繼承開始後，視為所得遺 產，由繼承人就所得遺產負清償責任','繼承人雖對被繼承人之債務，以繼承所得遺產為限負連帶清償責任，但於法院公示催告債權人申 報債權期間，繼承人不得對任何債權人償還債務',null,'民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('107-3301-047','107-3301',47,'single_choice',2,'被繼承人甲死亡時，遺產有A 地、B 車、在C 銀行的存款100 萬元。繼承人為成年子女乙、丙、丁 共三人，尚未完成遺產分割。設下述之第三人戊為惡意（知悉遺產繼承人為乙、丙、丁三人），乙、 丙共同所為之下列行為，何者立即確定有效？','將A 地出售予第三人戊，並移轉A 地所有權予戊','將B 車出售予第三人戊，並移轉B 車所有權予戊','提領C 銀行內的存款100 萬元','將各自對遺產三分之一之應繼分出售予第三人戊，使遺產為丁、戊共有',null,'民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('107-3301-048','107-3301',48,'single_choice',2,'甲男、乙女為夫妻，有子女丙、丁、戊三人。甲生前因丙結婚給與50 萬元；因丁結婚給與40 萬元； 因戊營業而給與100 萬元；於乙出國旅遊時給與20 萬元。關於歸扣權利人，下列敘述，何者正確？','乙為歸扣權利人，丙、丁、戊則否','乙、丁為歸扣權利人，丙、戊則否','乙、丙、丁為歸扣權利人，戊則否','乙、丙、丁、戊均為歸扣權利人',null,'民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('107-3301-049','107-3301',49,'single_choice',2,'被繼承人甲死亡時，遺產為90 萬元。甲有妻乙、長子丙、次子丁。丁之配偶為戊，丁、戊之間育有 一女己。設乙、丁均拋棄繼承，甲之遺產應如何分配？','丙繼承45 萬元，戊繼承22.5 萬元，己繼承22.5 萬元','丙繼承45 萬元，己繼承45 萬元','丙繼承60 萬元，己繼承30 萬元','丙繼承90 萬元',null,'民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('107-3301-050','107-3301',50,'single_choice',2,'甲立遺囑載明乙、丙為共同受遺贈人，均分甲之銀行存款100 萬元，若其中一人先死亡時，由另一 人承受該100 萬元。某日，乙、丙吵架，乙竟持刀殺丙致死而受刑之宣告。下列敘述，何者正確？','乙因甲之宥恕而得承受該100 萬元之遺贈','由甲之繼承人取得該100 萬元','由丙之繼承人取得該100 萬元','由乙與丙之繼承人共同取得該100 萬元',null,'民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('107-3301-051','107-3301',51,'single_choice',2,'關於權利之行使方式，下列敘述，何者正確？','在原告甲基於價金債權訴請判命被告乙償還價金50 萬元之本案訴訟程序上，如乙有意對甲主張借 款債權50 萬元並據此提出抵銷之抗辯時，得以反訴之方式聲明求受訴法院判決：准乙之50 萬元 借款債權與甲之50 萬元價金債權相抵銷','不定期限租賃A 地之出租人甲有意對承租人乙請求增加給付租金時，得向乙寄發存證信函載明： 台端承租A 地後，土地市價已大有提升，請自本函送達之翌日起每月增加給付租金5 萬元等旨， 藉此使甲、乙間自乙收受該函之翌日起發生法律上調整租金之效力','A 車為甲、乙所共有，為請求回復共有物，甲一人為原告，列丙為被告，主張丙為無權占有人， 訴請判決命丙將A 車返還於甲及乙二人（本訴訟）。本訴訟經確定判決甲勝訴後，丁有意主張其 於本訴訟繫屬後從丙善意取得A 車所有權時，得向甲、乙及丙同時寄發存證信函載明：本人（丁） 不知本訴訟繫屬情事，已在中古車買賣市場善意買受A 車而取得所有權，所以本訴訟之確定判決 所生效力不及於本人（丁）等旨，藉此使甲、乙、丙及丁等人間之法律關係終局確定','某大學同學會已經辦妥法人登記在案，其會員甲有意主張該同學會於某年月日所作成之某項大會 決議在召集程序上有重大瑕疵而得予以撤銷時，得起訴列該同學會為被告、其理事長乙為法定代 理人，聲明求為判決：該決議應予撤銷',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('107-3301-052','107-3301',52,'single_choice',2,'原告甲列乙為被告，聲明求為判決命乙將坐落A 地上之B 屋拆除後，將A 地返還予甲、丙及丁等3 人，主張：A 地係甲、丙及丁公同共有，乙擅自在A 地上興建B 屋，爰依所有權妨害排除請求權及 所有物返還請求權為請求。甲並提出丙、丁同意甲提起本件訴訟之證明書為證（本訴訟）。對此， 被告乙請求駁回原告之訴，向受訴法院表示不爭執甲所提該證明書之記載內容，惟主張乙就A 地有 使用權。下列敘述，何者正確？','法院應向甲闡明追加丙、丁為原告後，始得進行本案審理及辯論','法院應依職權將本訴訟繫屬程度及每次開庭期日一一通知丙及丁','如丁在本訴訟繫屬中，又列乙為被告，起訴（後訴訟）聲明求為判決命乙將B 屋拆除，將A 地返 還予甲、丙及丁等3 人，主張：A 地為該3 人公同共有，被乙擅自蓋建B 屋所占有，所以原告得 在訴訟上行使所有權妨害排除請求權及所有物返還請求權云云。此時，受理後訴訟之法院不得逕 行本案審理程序，而應認為後訴訟欠缺起訴之合法要件予以裁定駁回','如甲就本訴訟獲敗訴判決確定，而丙就本訴訟未曾受訴訟告知，則丙尚得提起同一訴訟以求救濟',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('107-3301-053','107-3301',53,'single_choice',2,'下列何者不屬於辯論主義（或當事人提出主義）之內容？','當事人應就訴訟關係為事實上之陳述','當事人應依民事訴訟法之規定，聲明所用之證據','原告於判決確定前，得撤回訴之全部或一部；訴經撤回者，視同未起訴','當事人主張之事實，經他造於準備書狀內或言詞辯論時或在受命法官、受託法官前自認者，無庸 舉證',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('107-3301-054','107-3301',54,'single_choice',2,'下列人員所為訴之撤回經被告同意之情形，何者不發生訴訟法上撤回之效力？','原告為無訴訟能力者之法定代理人','在訴請確認收養關係存在事件，原告為17 歲之未成年人，經家事法院為其利益依法選任程序監理 人時，該程序監理人在原告本人向受訴法院表明同意後所為訴之撤回','在選定人未限制被選定人撤回起訴之權限時，被選定人（原告）所為訴之撤回','在財產權訟爭事件，受訴法院之審判長依民事訴訟法所選任之特別代理人',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('107-3301-055','107-3301',55,'single_choice',2,'下列敘述之情形，何者具有訴之利益？','在扶養費裁判酌給請求事件，於其命為給付之裁判確定前，給付義務人以該裁判所酌定給付之金 額過高為理由，另行起訴請求判決確認該過高金額之債權不存在','在抵押權之被擔保債權為借款債權之情形，抵押權人起訴請求法院判決准許拍賣抵押物','起訴請求判決確認訴訟費用額','在本票之發票人拒不依執票人之請求為履行時，執票人起訴請求給付本票票款',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('107-3301-056','107-3301',56,'single_choice',2,'甲及乙為原告，列丙為被告，於106 年5 月1 日起訴，請求管轄法院裁判分割A 地，主張：A 地為 甲、乙及丙等3 人按應有部分各三分之一所共有，因如何分割該地未能達成協議，為此請法院裁判 予以分割等語（本訴訟）。下列敘述，何者錯誤？','在被告丙於106 年5 月3 日將其應有部分移轉登記予丁之情形，法院在審理當事人適格有無欠缺 時，不必依職權或命原告改列丁為被告','在本訴訟，如原告在訴之聲明就A 地之分割方法亦為具體之表明，而法院經本案審理之結果得心 證認為原告表明之該分割方法不盡公平時，受訴法院得依職權酌定分割方法','在本訴訟，如原告在訴之聲明就A 地之分割方法亦為具體之表明時，此項表明不得作為法院整理 相關事實及證據之基礎','在被告丙於106 年4 月3 日已經將其應有部分為戊銀行設定抵押權登記，又於106 年5 月3 日將 其應有部分移轉登記予丁之情形，本訴訟之受訴法院除依職權將本訴訟繫屬程度通知丁外，亦得 通知戊',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('107-3301-057','107-3301',57,'single_choice',2,'關於共同訴訟，下列敘述，何者正確？','就他人間之訴訟，對其訴訟標的之全部或一部，為自己有所請求者，如未於第一審或第二審言詞 辯論終結前，以其當事人兩造為共同被告，向本訴訟繫屬之法院起訴者，即不得再另行起訴','訴訟標的對於共同訴訟之各人必須合一確定者，共同訴訟人中一人提起合法上訴，其上訴效力及 於全體','共同訴訟人中一人有訴訟裁定停止之原因者，法院應依職權裁定停止訴訟程序，停止期間最長以4 個月為限','訴訟標的對於數人必須合一確定而應共同起訴，如其中一人拒絕同為原告而無正當理由者，法院 應依職權命該未起訴之人於一定期間內追加為原告，逾期未追加者，視為已一同起訴',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('107-3301-058','107-3301',58,'single_choice',2,'關於當事人能力與當事人適格，下列敘述，何者正確？','依公寓大廈管理條例所成立之大樓管理委員會具有當事人能力','以公益為目的之社團法人，經其目的事業主管機關許可，於章程所定目的範圍內，得逕對侵害多 數人利益之行為人提起不作為之訴及請求損害賠償，以維護公益','多數有共同利益之人為同一公益社團法人之社員者，於章程所定目的範圍內，得選定該法人之法 定代理人為選定人起訴','依選定當事人制度所選出之被選定人有數人者，其中一人死亡時，法院得依聲請裁定停止訴訟程序',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('107-3301-059','107-3301',59,'single_choice',2,'甲以乙為被告，於民國107 年3 月7 日向臺灣臺中地方法院起訴，請求清償借款。受訴法院於言詞 辯論時，發現乙已於同年2 月28 日死亡，應如何處理？','以裁定駁回起訴','以無理由判決駁回起訴','以裁定停止訴訟程序','該訴訟程序當然停止',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('107-3301-060','107-3301',60,'single_choice',2,'原告張三向管轄之地方法院訴請被告李四清償借款，於言詞辯論時，兩造在受訴法院成立和解，嗣 因和解筆錄上原告姓名誤書為張二，原告張三乃具狀聲請予以更正，法院受理後應如何更正？','由合議庭三位法官以裁定更正','由審判長以裁定更正','由受命法官以裁定更正','由書記官以處分更正',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('107-3301-061','107-3301',61,'single_choice',2,'關於法院踐行爭點整理之方法及步驟，下列選項所排列之順序，何者正確？①曉諭當事人具體主張 主要事實及有關聯性之間接事實 ②確認兩造當事人就主要事實及關聯性間接事實有無爭執 ③曉 諭原告就訴訟標的之特定為敘明或補充 ④曉諭當事人就事實上爭點聲明證據方法','①②③④','②④③①','③①②④','④①②③',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('107-3301-062','107-3301',62,'single_choice',2,'甲、乙及丙等三人共乘一輛汽車，105 年12 月1 日在某交叉路口與丁駕車相撞，造成損害甲為新臺 幣（下同）8 萬元、乙為9 萬元、丙為10 萬元，為此乙及丙乃選定甲為原告，起訴請求丁賠償三人 所受損害。關於本件訴訟，下列敘述，何者正確？','甲起訴之聲明應表明：被告丁應賠償原告27 萬元','在甲為乙及丙所提起之本件訴訟審理過程，受訴法院應依職權將本訴訟之爭點通知於乙及丙，始 得進行本案審理及判決','被告丁在本件訴訟之爭點整理過程向受訴法院承認乙確有受損害9 萬元之事實時，此項承認對於 甲所受損害請求之部分亦生自認之效力','甲在本案審理過程向法院承認丙曾經在訴訟外受丁賠償10 萬元時，縱使丙當時未到庭在場見證， 甲所為該項承認僅就丙請求損害賠償部分對受訴法院生拘束力',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('107-3301-063','107-3301',63,'single_choice',2,'關於當事人訊問之規定，下列敘述，何者錯誤？','法院得於訊問前或訊問後命當事人具結','法院訊問當事人之法定代理人者，準用當事人訊問之規定','當事人經具結後而故意為虛偽陳述，足以影響裁判之結果者，法院得以裁定處罰鍰','當事人無正當理由不到場者，法院得以裁定處罰鍰',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('107-3301-064','107-3301',64,'single_choice',2,'關於鑑定，下列敘述，何者正確？','當事人於訴訟前自行委請司法院認可之專業機關出具之鑑定意見書，應定性其證據方法為「鑑定」','鑑定人因已出具專業書面鑑定報告，故無到場陳述及具結之義務','法院選任經兩造合意之鑑定人後，當事人始知悉該人有拒卻之原因，仍得聲明拒卻','法院選任經兩造合意之鑑定人者，其所出具之鑑定意見書，法院應受拘束',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('107-3301-065','107-3301',65,'single_choice',2,'有關訴訟上和解及調解，下列敘述，何者錯誤？','因試行和解或進行調解程序，雖當事人已有委任訴訟代理人，且授與和解之特別代理權，受訴法 院或承辦調解之法官，仍得命當事人或其法定代理人親自到場','經法院命當事人或法定代理人親自到場，而無正當理由，未於和解期日或調解期日到場者，法院 均得以裁定處以新臺幣3,000 元以下之罰鍰','就訴訟或調解之爭議事件有利害關係之第三人，受訴法院或承辦調解之法官，均得依職權通知參 加和解或調解程序','具有法律上利害關係之第三人，非因可歸責於自己之事由，未參加和解或調解者，得對已成立之 和解或調解，提起第三人撤銷訴訟',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('107-3301-066','107-3301',66,'single_choice',2,'甲起訴主張乙於106 年12 月10 日向其借款新臺幣（下同）100 萬元，約明乙應於107 年1 月10 日 返還，乙於借款時同時簽發同面額之本票一張交與甲收執，作為借款憑證，惟屆期乙並未清償，表 明依消費借貸法律關係，請求乙返還100 萬元，並檢附乙簽發之本票為證。第一審法院獨任法官定 於107 年3 月13 日進行第一次言詞辯論程序，屆期乙不到場，甲聲請由其一造辯論判決。下列敘述， 何者正確？','言詞辯論期日通知於107 年3 月4 日合法送達於乙，乙未於言詞辯論期日到場，甲乃聲請法院由 其一造辯論判決，法院應准其聲請','甲慮及其對消費借貸關係存在之事實，恐舉證有所未足，遂於107 年3 月12 日具狀追加依票據法 律關係為請求，該追加書狀未送達於乙，法院認甲於起訴時已提出該本票為證，該書狀繕本已送 達於乙，乙應知悉其事，得准甲之聲請，由其一造辯論而為判決','乙曾提出書狀，抗辯其已清償，並提出銀行之匯款單為證，法院得准甲為一造辯論，並於斟酌乙 提出之書證及所附證物後，為甲敗訴之判決','甲於言詞辯論期日始聲明證據而偕同證人丙到場，聲請訊問丙以證明甲、乙消費借貸之經過，法 院見丙已到場，為免證人多次奔波，乃訊問之，訊問後得由甲一造辯論而為判決',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('107-3301-067','107-3301',67,'single_choice',2,'關於起訴行為，下列敘述，何者正確？','破產人為破產財團權利歸屬主體，故破產管理人為破產財團起訴時，應列破產人為原告，由破產 管理人為法定代理人，始為合法','原告依據金錢債權起訴，為表明訴訟標的，僅於起訴狀上記載原因事實，而未表明其實體法上請 求權基礎時，此項起訴不合程式','原告甲對被告乙訴請判決准兩造離婚，主張：乙近年來再三對甲施加暴力以致甲生活起居深感痛 苦，已難繼續維持雙方之婚姻關係等語，此項起訴狀上之記載尚難認為其有未表明訴訟標的之不 合程式','在請求金錢賠償損害之訴，原告於起訴時，應於訴狀內表明全部請求金額，如僅表明在原因事實 範圍內全部請求之最低金額，係屬起訴不合程式',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('107-3301-068','107-3301',68,'single_choice',2,'關於當事人兩造成立之協議，下列何者，不生效力？','就兩造爭執之某事實存否，於法院決定要行鑑定時，選定某專家為鑑定人之協議','就當事人一造對他造今後之加害行為所致損失，受害之他造均不起訴請求法院裁判之協議','就應適用辯論主義（協同主義）之應證事實，分配由一造當事人就該事實存否負證據提出責任之 協議','在甲為履行損害賠償債務而簽發某面額支票交付乙作為清償方法後，甲、乙間成立乙在甲不履行 債務時，僅得以該損害賠償請求權（不以票款支付請求權）為訴訟標的起訴之協議',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('107-3301-069','107-3301',69,'single_choice',2,'於本案判決發生既判力後，下列敘述之何項事實主張，為既判力所未遮斷？','在某買賣價金給付請求事件，於起訴前被告已為清償之事實','在原告基於買賣契約請求判命被告給付價金之事件，該當於買賣契約為無效之事實','在原告訴請確認其與被告之租賃關係存在之事件，就該租賃關係已於起訴日經終止權人行使終止 權之事實','在原告甲對被告乙訴請返還借款事件，事實審言詞辯論終結後對該借款債權為抵銷之事實',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('107-3301-070','107-3301',70,'single_choice',2,'下列敘述，何者屬於起訴狀之應記載事項？','在以債權請求為訴訟標的之情形，其特定所需原因事實之記載','關於定審判權所需原因事實之表明','應受判決事項之聲明所依據之事實及理由','在有選定當事人之情形，其選定人之表明',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
('107-3301-071','107-3301',71,'single_choice',2,'對於第一審法院所為終局判決所提起之上訴，下列敘述，何者正確？','對於第一審法院依簡易訴訟程序所為終局判決，其上訴利益逾民事訴訟法所定得上訴於第三審之 額數者，得逕向第三審法院提起上訴','對於第一審法院依簡易訴訟程序所為終局判決，其上訴利益逾民事訴訟法所定得上訴於第三審之 額數者，縱使經當事人合意，亦不得逕向第三審法院提起上訴','對於第一審法院依小額訴訟程序所為終局判決，縱非主張其違背法令為理由，亦得提起第二審上訴','對於第一審法院就簡易訴訟事件適用通常訴訟程序所為終局判決，經上訴於第二審法院後，其審 理應適用通常訴訟程序',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
('107-3301-072','107-3301',72,'single_choice',2,'關於訴訟程序之停止，下列敘述，何者錯誤？','當事人以訴訟中有犯罪嫌疑牽涉其裁判者為由，聲請法院裁定在該犯罪之刑事訴訟程序終結前停 止訴訟程序，在法院尚未裁定准許前，當事人依法仍有如期到場為言詞辯論之義務','當事人兩造均經合法通知遲誤言詞辯論期日而無正當理由者，除別有規定外，視為合意停止訴訟 程序，但法院認為必要時得依職權續行訴訟','兩造當事人於某日向受訴法院陳明合意停止訴訟程序後，如原告於1 個月內聲請續行訴訟，經法 院定期進行言詞辯論，兩造無正當理由仍遲誤不到，應視為撤回其訴','當事人不遵審判長所命預納費用，致訴訟無從進行，他造亦不遵期墊支費用時，視為合意停止訴 訟程序。逾期4 個月仍未預納或墊支者，視為撤回其訴',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
('107-3301-073','107-3301',73,'single_choice',2,'關於上訴，下列敘述，何者錯誤？','第一審法院為原告部分勝訴、部分敗訴之判決，被告不服提起上訴，原告得於其上訴期間屆滿後， 就其敗訴部分，提起附帶上訴','第一審法院依原告備位聲明為其勝訴之判決，被告提起上訴後，第二審法院認原告（被上訴人） 之備位請求為無理由時，應審理原告（被上訴人）之先位請求','原告甲依據A、B 兩請求權，請求法院擇一判命被告乙給付300 萬元，第一審判決認A 請求權有 理由，為甲勝訴之判決。乙不服提起上訴，第二審法院認A 請求權無理由時，應審理B 請求權有 無理由','甲依據買賣契約起訴請求乙移轉A 地所有權，第二審法院審理時，乙抗辯甲尚有價金300 萬元未 給付，第二審法院判命乙應於甲給付300 萬元之同時，將A 地所有權移轉登記與甲，甲僅就命其 給付逾100 萬元部分提起上訴，第三審法院認甲之上訴有理由時，應將第二審判決全部廢棄發回',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
('107-3301-074','107-3301',74,'single_choice',2,'關於第三人撤銷訴訟程序，下列敘述，何者正確？','此項訴訟程序之設立，有助於同時兼顧擴大訴訟制度解決紛爭之功能及貫徹程序權保障之要求','適用此項訴訟程序所得之確定判決，對於既判力主觀範圍之大小不生影響','凡確定判決效力所及之第三人受不利益影響者，均得起訴請求撤銷該判決對自己不利益之部分','於確定判決發生對世效之情形，不得依第三人撤銷訴訟程序請求救濟',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
('107-3301-075','107-3301',75,'single_choice',2,'關於第三審程序，下列敘述，何者正確？','上訴人委任某律師為訴訟代理人提起第三審上訴，未於上訴狀內表明上訴理由者，如未於提起上 訴後之法定補正期間內補正，原審法院毋庸命其補正，得逕以裁定駁回其上訴','對於第一審判決未經向第二審法院上訴之當事人，對於維持該判決之第二審判決，仍得提起第三 審上訴','上訴人提起第三審上訴，未繳納第三審裁判費，經原審裁定限期命其補繳，上訴人嗣又減縮其上 訴聲明，然未於限期內繳交任何裁判費者，原審法院應依其減縮後之聲明再次裁命補繳裁判費， 倘仍未遵期補繳，始可裁定駁回其上訴','訴訟經第三審法院為發回判決者，上訴人於發回後之第二審程序，不得擴張上訴聲明',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
('107-3301-076','107-3301',76,'single_choice',2,'關於上訴人撤回其對第一審判決之上訴，下列敘述，何者正確？','兩造都上訴後，原告撤回上訴，在第二審法院審理被告之上訴程序中，原告不得再就原判決其敗 訴部分聲明上訴','原告上訴後，被告提起附帶上訴，原告撤回上訴，須得被告同意','原告上訴，在收到第二審言詞辯論期日通知書後具狀撤回上訴，翌日反悔，又具狀撤回其撤回上 訴之意思表示，第二審法院應續行訴訟行為而辯論及判決','原告撤回上訴後，法院應退還其所繳納第二審之全部裁判費',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],12,12,'parsed','pending_manual_review',null,true),
('107-3301-077','107-3301',77,'single_choice',2,'甲主張：乙曾向其借款新臺幣（下同）80 萬元，已屆清償期，卻仍未返還，據此向法院聲請對乙核 發支付命令等語，並提出有提領80 萬元紀錄之存摺影本為證，下列敘述，何者錯誤？','法院於裁定前，不得訊問乙','法院毋庸命甲提出借據影本或其他借款憑證','乙收受支付命令後，若依法聲明異議，甲與乙得合意請求法院適用簡易訴訟程序為本案審理','乙收受支付命令後，聲明異議時應附具理由',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],12,12,'parsed','pending_manual_review',null,true),
('107-3301-078','107-3301',78,'single_choice',2,'甲男、乙女為夫妻，因無法生育，遂偽造出生證明，將丙男與丁女所生之A 子辦理戶籍登記為甲、 乙之婚生子女，若A 成年後浪費成性，甲反悔而欲否認甲、A 間之父子關係，下列敘述，何者正確？','甲應以乙、A 為被告，提起否認子女之訴','若A 自認其非甲、乙所生，法院不得依職權調查證據，應即為甲勝訴之判決','甲得以A 為被告，提起確認甲、A 親子關係不存在之訴','甲知悉A 並非婚生子女已逾2 年，不得再提起確認親子關係不存在之訴',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],12,12,'parsed','pending_manual_review',null,true),
('107-3301-079','107-3301',79,'single_choice',2,'甲夫、乙妻於民國90 年結婚，婚後住臺東，95 年生女丙，98 年乙攜丙至娘家嘉義居住工作，甲、 乙二人聚少離多，感情生變，乙於105 年向嘉義地方法院起訴請求裁判離婚。有關離婚之訴訟程序， 下列敘述，何者正確？','離婚訴訟繫屬中，甲想起夫妻結婚時，並未宴客亦無公開儀式，僅自行至戶政事務所辦理結婚登 記，故至臺東地方法院起訴確認甲、乙間之婚姻無效，臺東地方法院應裁定停止訴訟，以免與嘉 義地方法院之前開離婚裁判互相矛盾','嘉義地方法院判決准甲、乙離婚，甲並未上訴，該離婚判決確定後，甲才想起結婚時，並未宴客 亦無公開儀式，故至臺東地方法院另行起訴確認甲、乙間之婚姻無效，臺東地方法院應就甲、乙 之婚姻是否有無效事由，為實體審理','乙以甲、乙間未共同生活長達7 年，有難以維持婚姻之重大事由，提起離婚訴訟，嘉義地方法院 對此訴訟有管轄權','本件離婚訴訟繫屬中，甲因意外死亡，此時離婚訴訟程序當然停止',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],12,12,'parsed','pending_manual_review',null,true),
('107-3301-080','107-3301',80,'single_choice',2,'甲夫列乙妻為相對人，向管轄法院提出聲請狀，主張甲不能維持生活而無謀生能力，乙卻不盡法定 扶養義務，求為裁判命乙自收受該書狀之日起至甲死亡之日止，按月給付甲新臺幣1 萬元。下列敘 述，何者正確？','法院為本案裁判時，得不受甲就給付方法之聲請意旨所拘束','在本案審理過程，甲提出之證據，如乙不同意予以調查時，法院不得加以調查','甲、乙於本案程序進行中，不得成立程序上和解，縱使成立和解亦不發生與本案確定裁判同一之 效力','在本案審理過程，乙得請求裁判確認甲、乙間之婚姻關係不存在。此時，兩造不得合意由原法院 適用原非訟程序審理乙之請求',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],12,12,'parsed','pending_manual_review',null,true),
('107-4301-001','107-4301',1,'single_choice',2,'A 股份有限公司為了在海外設廠而向銀行貸款新臺幣10 億元，廠房啟用後，產能倍增，獲利也大幅 躍進，董事長甲未經股東會決議即動用部分盈餘逕行償還所剩餘之銀行貸款。5 年後，B 股份有限公 司取得A 公司過半股權，發現此一情形，依公司法對甲提起侵權行為損害賠償之請求，下列敘述何 者正確？','以盈餘償還貸款，A 公司並無損害，B 公司之請求應屬無理由','此屬違反忠實義務之情形，故B 公司對甲之請求無理由','因B 公司未先向A 公司請求損害賠償，故B 公司對甲之請求無理由','B 公司之請求權已逾消滅時效，甲可提出時效抗辯',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('107-4301-002','107-4301',2,'single_choice',2,'依據公司法，齊備那些形式基準即得認為是公司法上之經理人？','職稱必須為總經理、副總經理等，且章程中規定公司得設置經理人','職稱必須為總經理、副總經理等，且已辦理經理人登記','經法定程序委任，且必須已辦理經理人登記','章程中規定公司得設置經理人，且必須經法定程序委任',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('107-4301-003','107-4301',3,'single_choice',2,'甲男為X 股份有限公司董事長，為追求心儀之乙女，X 公司增資新臺幣1,000 萬元讓乙全額認購， 並辦妥登記，惟乙並未實際繳納股款，甲也未要求乙繳納。此一情形被員工匿名向檢察機關檢舉， 已由檢察官提起公訴審理中。依據公司法，下列敘述何者正確？','乙須負刑事責任，甲則無刑事責任','甲與乙可能須連帶賠償公司因而所受之損害','有罪判決確定後，法院應通知中央主管機關撤銷或廢止X 公司登記','有罪判決確定後，若經主管機關限期補正，且乙已補正後，即可無須撤銷或廢止X 公司登記',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('107-4301-004','107-4301',4,'single_choice',2,'A 資訊股份有限公司（下稱A 公司）實收資本為新臺幣（下同）1,000 萬元。A 公司全部總資產為 1,100 萬元、總負債為100 萬元。A 公司擬貸款與常有業務往來之B 有限公司（下稱B 公司）共500 萬元，但要求B 公司提供其所有土地設定抵押擔保該貸款。下列關於A 公司貸與行為效力及理由之 敘述，何者正確？','有效，因貸與金額未超過實收資本一定比例','無效，因貸與金額超過公司淨值一定比例','有效，因與B 公司常有業務往來','無效，因要求B 公司提供抵押擔保',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('107-4301-005','107-4301',5,'single_choice',2,'A 公開發行股份有限公司（下稱A 公司）以電子製造為業，實收資本額為新臺幣（下同）1 億元， 章程中並未有任何關於轉投資之規定。A 公司於投資B 食品有限公司2,000 萬元後，再以股東會決 議投資C 股份有限公司2,500 萬元。今A 公司擬投資D 股份有限公司100 萬元。以下是否需經股東 會決議及其理由之敘述何者正確？','本次投資無需股東會決議，因本次投資金額未達實收資本百分之四十','本次投資無需股東會決議，因前次投資C 公司時已有股東會決議','本次投資需股東會決議，因轉投資依法皆須由股東會決議','本次投資需股東會決議，因總投資金額已達實收資本百分之四十',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('107-4301-006','107-4301',6,'single_choice',2,'A 股份有限公司（下稱A 公司）之董事甲因涉嫌掏空公司資產而被法院假處分裁定暫停董事職務， A 公司擬以甲違反注意義務欲對其提起民事訴訟求償。試問以下何者最不適宜擔任A 公司訴訟之代 表人？','董事長乙','監察人丙','股東會推選之股東丁','股東會推選之非股東戊',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('107-4301-007','107-4301',7,'single_choice',2,'股票公開發行之A 股份有限公司擬出售公司位於市中心商業區的土地一筆，此為公司僅存之重要財 產，並列為今年股東會議案，公司章程對財產處置程序並無特別規定，依公司法規定，下列敘述何 者錯誤？','該議案應由三分之二以上董事出席之董事會，以出席董事過半數之決議提出之','若股東會當日有代表已發行股份總數過半數但未達三分之二的股東出席，經出席股東表決權三分 之二以上同意，該議案並未通過','若股東會當日有代表已發行股份總數三分之二以上股東出席之股東會，以出席股東表決權過半數 之同意，該議案通過','若股東會決議通過該議案，股東甲於決議前曾以書面通知公司反對該議案，並於股東會已為反對 者，得請求公司以當時公平價格收買其所有股份',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('107-4301-008','107-4301',8,'single_choice',2,'乙為股票未公開發行之B 股份有限公司股東，乙擬出具委託書委託他人出席股東會，下列敘述何者 錯誤？','乙以自行書寫之委託書委託代理人出席股東會，現行實務見解認為其委託合法','乙先委託丙，後再委託丁，但丁之委託書較丙之委託書早一日送達公司，則應以丁之委託書為準','乙以公司印發之委託書委託丙出席股東會，但又以電子方式行使表決權，則以電子方式行使之表 決權為準','自然人戊受乙及其他股東共計5 人委託出席股東會，其代理之表決權不得超過已發行股份總數表 決權之百分之三',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('107-4301-009','107-4301',9,'single_choice',2,'A 股份有限公司（下稱A 公司）章程所訂資本額為新臺幣（下同）5 億元，實收資本額為3 億元，A 公司已累積法定盈餘公積1 億元，無其他公積，A 公司去年營運遭遇首次虧損共計3,000 萬元，依公 司法規定，A 公司今年可否分派現金予股東？','可以，最高可分派2,500 萬元','可以，最高可分派7,000 萬元','可以，最高可分派7,500 萬元','不能分派',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('107-4301-010','107-4301',10,'single_choice',2,'下列有關股份有限公司會計及員工酬勞之敘述，依公司法規定及實務見解，何者錯誤？','公司依其業務之性質，自設立登記後，如需2 年以上之準備，始能開始營業者，經主管機關之許 可，得依章程之規定，於開始營業前分派股息','公司應於章程訂明以當年度獲利狀況之定額或比率，分派員工酬勞，其形式可以股票或現金為之， 並應由股東會以代表已發行股份總數三分之二以上股東出席之股東會，以出席股東表決權過半數 之決議行之。但公司尚有累積虧損時，應予彌補','公司於完納一切稅捐後，分派盈餘時，應先提出百分之十為法定盈餘公積。但法定盈餘公積，已 達實收資本額時，不在此限','公司非於盈餘公積填補資本虧損，仍有不足時，不得以資本公積補充之',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('107-4301-011','107-4301',11,'single_choice',2,'股票未公開發行之A 股份有限公司，經董事會決議買回股份，請問：以下何項買回目的，符合公司 法之規定？①轉讓股份予員工 ②配合附認股權公司債，作為股權轉換之用 ③為維護公司信用及 股東權益所必要而買回，並辦理銷除股份','①符合','①及③皆符合','②及③皆符合','①、②及③皆符合',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('107-4301-012','107-4301',12,'single_choice',2,'A 股份有限公司因董事均已辭任，股東會亦無選任清算人，經該公司債權人聲請法院選派甲律師為 清算人，下列關於A 股份有限公司清算之敘述，何者錯誤？','甲律師得由股東會決議解任','法院得因監察人聲請，將甲律師解任','甲律師之報酬由法院決定','甲律師之報酬由公司現存財產中儘先給付',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('107-4301-013','107-4301',13,'single_choice',2,'A 公開發行股票公司（下稱A 公司）已發行股份數為60 萬股，甲當選董事時持股1 萬股。就任董事 後，深覺公司前景可期再買進20 萬股，但事後因家人緊急就醫需龐大金錢支出，遂出賣持股10 萬 股。依實務見解，下列關於甲前開出售股份行為法律效果之敘述，何者正確？','因甲係為緊急醫療需求出售持股，故不影響其董事資格','因甲轉讓10 萬股已超過選任當時持股1 萬股之半數，故董事當然解任','因甲轉讓10 萬股後實際持股數仍高於選任持有股份之二分之一，故不影響其董事資格','因甲轉讓10 萬股已超過A 公司已發行股份總數十分之一，故董事當然解任',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('107-4301-014','107-4301',14,'single_choice',2,'甲任職A 股份有限公司（下稱A 公司）之監察人，下列權限，何者非屬公司代表權之類型？','列席A 公司董事會並陳述意見','查核A 公司表冊時委託會計師協助','監督A 公司業務之執行時委託律師協助','受股東會決議之委託代表A 公司向其董事提起民事訴訟',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('107-4301-015','107-4301',15,'single_choice',2,'股東行使股東提案權提出以下那些議案，公司必須列入開會通知？','修改公司章程選舉董事、監察人的方法，由累積投票制改為直接投票制','任期屆滿前，改選全體董事、監察人','為解決高階經理人薪酬過高的問題，應於章程中訂定經理人薪酬上限','公司規模逐漸成長，股東人數眾多，應向證券主管機關申請辦理公開發行程序',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('107-4301-016','107-4301',16,'single_choice',2,'關於再保險，下列敘述何者錯誤？','再保險人不得向原保險契約之要保人請求交付保險費','原保險人不得以再保險人不履行再保險金額給付之義務為理由，拒絕或延遲履行其對於被保險人 之義務','於原保險契約及再保險契約有約定下，原保險契約之被保險人得直接向再保險人請求給付','我國司法實務見解認為再保險無保險代位之適用',null,'保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('107-4301-017','107-4301',17,'single_choice',2,'下列何者非我國保險法規定得僱用保險業務員從事保險招攬之行業？','保險合作社','保險經紀人公司','兼營保險代理人業務之銀行','保險公證人公司',null,'保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('107-4301-018','107-4301',18,'single_choice',2,'下列有關保險契約之敘述，何者正確？','定額保險為契約上載明保險標的一定價值之保險契約','為避免事故時發生爭議，財產保險多為定值保險','因人身無價，人身保險均為不定值保險與不定額保險','財產保險契約之功能在填補損失',null,'保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('107-4301-019','107-4301',19,'single_choice',2,'A 銀行與B 保險公司訂立保險契約，約定銀行職員如有侵占公款，B 保險公司應予以理賠。甲任職 於A 銀行，乙為甲之人事保證人，今甲侵占公款百萬臺幣，B 保險公司賠付後，依保險法第53 條向 乙訴請給付該百萬臺幣。下列關於B 保險公司對乙之請求，有無理由之敘述，何者正確？','無理由，因保險法第53 條僅限侵權行為所生之損害賠償，本件屬保證責任','無理由，因乙為甲之人事保證人，A 銀行已經可以自保險公司獲得保險理賠，依民法第756 條之2 第1 項規定不得向乙請求，因此保險人亦不得向乙行使代位權','有理由，B 保險公司係代位A 銀行可得對第三人主張之損害賠償請求權，本件A 銀行可對乙主張， B 保險公司自得對乙為主張','有理由，因乙非保險法第53 條第2 項之「家屬」或「受僱人」',null,'保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('107-4301-020','107-4301',20,'single_choice',2,'甲參加A 公司之彩色粉塵派對活動，因A 公司人員用火不慎，導致甲受有嚴重燒燙傷，A 公司就該 活動已向B 保險公司投保公共意外責任保險。下列敘述，何者錯誤？','若保險契約無特別約定，B 保險公司應對A 公司為處理甲所提出之責任相關賠償請求所支出之抗 辯費用負給付之責','縱契約條款未約定，A 公司對甲所為之和解，未經B 保險公司參與，B 保險公司亦不受拘束','除被保險人對第三人應負損害賠償責任確定者外，B 保險公司在A 公司未向甲給付賠償金前，不 得給付A 公司保險金','甲對A 公司提起賠償請求經判決確定後，即得直接向B 保險公司請求給付保險金',null,'保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('107-4301-021','107-4301',21,'single_choice',2,'要保人或被保險人，如對於保險標的物未盡約定保護責任所致之損失，依保險法第98 條第1 項規定， 保險人得為下列何種主張？','解除契約','契約自始無效','不負保險責任','請求損害賠償',null,'保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('107-4301-022','107-4301',22,'single_choice',2,'保險人於承保前，如未查明保險標的物之市價超額承保，下列關於保險事故發生後，保險契約效力 之敘述，何者正確？','保險契約效力自始無效','要保人因給付較高保險費，故得主張給付超過保險標的價值之保險金','保險人得主張解除契約','超額承保部分無效',null,'保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('107-4301-023','107-4301',23,'single_choice',2,'甲以其子乙為被保險人，投保人壽保險附加傷害醫療保險，下列敘述何者錯誤？','乙如於14 歲身亡時，保險人不負給付死亡保險金之責','乙如於16 歲身亡時，保險人負給付死亡保險金之責','乙如於14 歲因意外傷害事故住院治療時，保險人不負給付醫療保險金之責','乙如於16 歲因意外傷害事故住院治療時，保險人負給付醫療保險金之責',null,'保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('107-4301-024','107-4301',24,'single_choice',2,'甲以自己為被保險人，投保日額型健康保險，投保4 個月後，經醫生檢查發現罹患大腸癌第四期， 住院治療，共住院10 日，惟確診前甲並無任何大腸癌跡象。嗣後，甲向保險人請求給付10 日之住 院醫療保險金，遭保險人以大腸癌第四期之形成需時超過4 個月，甲投保前應已罹患大腸癌為理由， 拒絕理賠。下列有關保險人之拒絕理賠有無理由之敘述，何者正確？','有理由，因投保前保險事故已發生','有理由，因甲違反據實告知義務','無理由，因甲投保時對自身大腸癌並不知悉','無理由，因僅投保時在妊娠中者，健康保險人始得拒賠，而甲罹癌非妊娠，亦非因生產住院',null,'保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('107-4301-025','107-4301',25,'single_choice',2,'下列有關保險業訂立保險金信託契約之敘述，何者錯誤？','信託契約之受益人應為保險契約之受益人','保險契約之要保人與被保險人須為同一人','保險業辦理保險金信託業務應設置信託專戶','保險業辦理保險金信託業務，除其他經主管機關核准之資金運用方式外，其資金運用範圍限於現 金或銀行存款、公債或金融債券、短期票券及不動產',null,'保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('107-4301-026','107-4301',26,'single_choice',2,'甲簽發本票一紙與乙，其上記載到期日為民國102 年2 月30 日，乙隨即背書轉讓丙，丙於同年3 月 2 日提示未獲付款，丙乃訴請甲、乙連帶給付票款，下列敘述何者正確？','本票到期日為曆法上不存在之日期，應將到期日解為發票日，丙之提示合法','本票到期日為曆法上不存在之日期，應解為該月末日為到期日，丙之提示合法','因到期日必為可能之日期，曆法上不存在者，乃不可能提示與付款，該本票欠缺應記載事項應屬 無效','曆法上所無之到期日，應解為該月末日為到期日，丙之提示逾期對乙喪失追索權',null,'票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('107-4301-027','107-4301',27,'single_choice',2,'甲簽發未載發票日之支票數張交予乙，並已決定以嗣後每月之15 日為發票日，囑託乙逐月照填一張， 以完成發票行為。依實務見解，此類票據之效力如何？','我國法並不承認空白票據，故縱乙完成填載發票日，亦應屬無效','發票日為票據之絕對必要記載事項，故縱乙完成填載發票日，亦應屬無效','此類票據為有效，若乙於填載發票日前遺失票據，並得為公示催告','乙為甲之使者或機關，於乙填載發票日完成後，票據應屬有效',null,'票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('107-4301-028','107-4301',28,'single_choice',2,'甲簽發本票以清償向乙借款新臺幣1 萬元整，雙方有借貸契約為憑。但簽發本票時不慎將金額誤寫 為新臺幣2 萬元整。若乙將該本票轉讓予善意之丙，且丙有給付乙新臺幣1 萬9 千5 百元作為取得 該本票之對價。丙於本票到期時可向甲請求多少金額？','新臺幣1 萬元，因為甲、乙間之借貸契約已明定','新臺幣2 萬元，因為以票據文義為準','新臺幣1 萬9 千5 百元，因為丙僅支付乙新臺幣1 萬9 千5 百元','新臺幣0 元，因為該本票有瑕疵而無效',null,'票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('107-4301-029','107-4301',29,'single_choice',2,'若匯票上記載付款人為甲，票載金額為新臺幣10 萬元整、到期日為民國105 年3 月1 日。甲知執票人 為乙，乃提前於民國105 年2 月28 日對乙付款，但僅願支付新臺幣5 萬元整，下列敘述何者正確？','甲雖為一部付款，但執票人乙不得拒絕','因甲為一部付款，故執票人乙得拒絕','因甲為提前付款，故執票人乙得拒絕','因甲為期後付款，故執票人乙不得拒絕',null,'票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('107-4301-030','107-4301',30,'single_choice',2,'甲簽發面額10 萬元之匯票一張交付受款人乙，到期日為民國98 年7 月1 日，A 為付款人，乙背書 交付丙，乙並指定在付款地之B 為預備付款人，丙空白背書交付丁，丁交付戊，戊於98 年7 月3 日 向A 請求付款被拒，於作成拒絕證書後對丙追索，丙對戊有無抗辯事由？','丙對戊無抗辯事由，因戊已遵期提示請求付款','丙對戊有抗辯事由，因戊違反應向預備付款人為參加付款提示之規定','丙對戊有抗辯事由，因背書不連續','丙對戊有抗辯事由，因戊未遵期提示請求付款',null,'票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('107-4301-031','107-4301',31,'single_choice',2,'甲簽發一紙發票日為民國105 年1 月1 日、到期日為民國105 年3 月1 日之記名本票給乙，乙立即 將之背書轉讓給丙，丙於民國105 年3 月10 日向甲提示付款被拒後，下列敘述何者正確？','執票人丙尚未逾越付款之提示期間，故丙對甲、乙均得主張追索權','執票人丙逾越付款之提示期間，故喪失對前手之追索權，故丙對甲、乙不得行使追索權','執票人丙逾越付款之提示期間，喪失對前手之追索權，但因發票人甲負絕對付款責任，故丙對甲 仍得主張票據權利，但對乙喪失追索權','執票人丙逾越付款之提示期間，但執票人丙對發票人甲之追索權時效期間為3 年，對背書人之追 索權時效為1 年，故丙對甲、乙均得行使追索權',null,'票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('107-4301-032','107-4301',32,'single_choice',2,'甲簽發本票一張，簽名並記載金額後交付給乙，乙未察知未記載發票日，背書轉讓給丙，下列敘述 何者正確？','此本票為空白授權票據，因為甲、乙均在本票上有簽名，故均要依票據文義對丙負責','票據行為具有無因性，因甲、乙均在本票上簽名，故應依票據文義對丙負責','此本票欠缺應記載事項，所以發票人甲及背書人乙均得以此做為物之抗辯，對丙主張本票無效','此本票欠缺應記載事項，所以發票人甲得對丙主張發票行為無效，但背書人乙之背書仍有效，因 為票據行為具有獨立性',null,'票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('107-4301-033','107-4301',33,'single_choice',2,'甲於99 年3 月20 日簽發一紙發票日為99 年5 月20 日之支票給乙，乙將該票背書轉讓給丙，丙再 背書轉讓給丁，而丁見該票有好友乙之背書，其遂將乙之背書塗銷掉。其後丁又再將支票記名背書 轉讓給戊，且其背書時於票上記載禁止轉讓，最後戊又於99 年4 月30 日將該票背書轉讓給庚，惟 此支票於99 年5 月24 日被拒絕付款，並附有退票理由單。何人對庚負有票據責任？','甲、戊','甲、丙、戊','甲、丙、丁、戊','甲、乙、丙、丁、戊',null,'票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('107-4301-034','107-4301',34,'single_choice',2,'甲簽發支票一紙予乙，發票地在苗栗縣，付款地在新竹縣，發票日為105 年3 月10 日，乙至遲應於 何日以前提示付款？','同年3 月16 日','同年3 月17 日','同年3 月24 日','同年3 月25 日',null,'票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('107-4301-035','107-4301',35,'single_choice',2,'甲簽發發票日為102 年6 月1 日、面額10 萬元之支票一紙交付受款人乙，乙背書交付丙，丙背書交 付丁，若A 銀行為付款人，並於支票上載明照付並簽名。下列敘述何者正確？','甲與乙均應負票據責任','支票遺失時丁得為止付','丁應遵守付款提示期間','A 銀行之付款責任與匯票承兌人同',null,'票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('107-4301-036','107-4301',36,'single_choice',2,'非公開發行之A 電影事業股份有限公司，為籌拍介紹國寶級製琴名師之紀錄片，依證券櫃檯買賣中 心創櫃板管理辦法之規定，登錄創櫃板，就A 公司辦理現金增資時依公司法第267 條規定保留予員 工及原股東認購而其未認購之部分，向投資大眾發行普通股股票籌資。關於A 公司登錄創櫃板發行 普通股之籌資行為，下列敘述何者正確？','A 公司於創櫃板發行之普通股係經金融監督管理委員會核定豁免申報之有價證券','該籌資行為係屬私募，無須依證券交易法向金融監督管理委員會申報','該籌資行為係依公司法第267 條規定向特定人募股，無須向主管機關申報','A 公司登錄創櫃板後，即有證券交易法第157 條之1 內線交易禁止規定之適用',null,'證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('107-4301-037','107-4301',37,'single_choice',2,'A 公開發行公司擬申請上市，經股東常會決議，於章程中明定設3 位獨立董事，並設立審計委員會， 另設薪資報酬委員會。試問下列敘述何者正確？','監察人為公司必備之內部機關，雖設立審計委員會，仍須設監察人','審計委員會須由全體3 位獨立董事所組成；但薪資報酬委員會僅須1 位獨立董事即為已足，其餘 成員得由非獨立董事擔任','獨立董事3 人中如有1 人離職時，應於60 日內召開股東臨時會補選之','獨立董事於任期中轉讓超過選任當時所持有之公司股份數額二分之一時，該獨立董事當然解任',null,'證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('107-4301-038','107-4301',38,'single_choice',2,'A 上市公司之董事甲於A 公司股票停止過戶期間中之某日，於集中交易市場出售其持有之A 公司股 票7 張，試問甲出售該等股票行為之法律效力為何？','有效，甲於集中交易市場出售該等股票之行為並未違法','有效，雖違反證券交易法之規定，但為維護交易安全及市場秩序仍屬有效，主管機關將對甲處以 新臺幣24 萬元以上240 萬元以下之罰鍰','無效，因甲出售該等股票之時點係在A 公司股票停止過戶期間','無效，因須先向主管機關申報，並於申報之日起3 日後，方得於集中交易市場出售該等股票',null,'證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('107-4301-039','107-4301',39,'single_choice',2,'A 上市公司有意入主B 上市公司取得經營權，惟因B 公司經營階層反對，A 公司遂決定公開收購B 公司已發行有表決權股份總數24.99%之普通股股票及美國存託憑證，關於本次公開收購，下列敘述 何者錯誤？','A 公司應提出具有履行支付收購對價能力之證明，向主管機關申報並公告特定事項後，始得進行 公開收購','A 公司及其關係人於公開收購期間，得於市場上購買B 公司無表決權特別股股票','A 公司得視B 公司股東實際應賣情形，延長或縮短公開收購期間','A 公司證明B 公司財務狀況發生重大變化並經主管機關核准後，即得停止公開收購',null,'證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('107-4301-040','107-4301',40,'single_choice',2,'A 上市公司因第4 季展望不如預期，股價在法說會隔天重挫跌停，董事會為維護公司信用及股東權 益，決定實施庫藏股護盤，預計自11 月2 日至12 月20 日，自集中交易市場買回5,000 張股票， 價格在90~160 元之間，預定買回股份占A 公司已發行股份總數之比率為1.57%。試問下列敘述何 者錯誤？','A 公司實施庫藏股之決議須經董事會三分之二以上董事之出席及出席董事超過二分之一同意','此次A 公司買回500 萬股占公司已發行股份總數1.57%，係屬合法','A 公司收買股份之總金額，不得逾保留盈餘加發行股份溢價及已實現之資本公積之金額','A 公司應於買回之日起3 年內將買回之股份轉讓；逾期未轉讓者，視為公司未發行股份，並應辦 理變更登記',null,'證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('107-4301-041','107-4301',41,'single_choice',2,'A 公司為一家從事記憶體製造之上市公司。為響應政府南向政策，該公司擬就章程所定股份總數內 尚未發行的部分，以每股新臺幣60 元之價格發行新股，籌措公司於馬來西亞設廠所需之資金。依證 券交易法之規定，下列敘述何者最正確？','A 公司所發行之新股仍應向證交所申請上市後才可以上市','A 公司之原有股東認購此批新股時，發行人或證券承銷商無需向其交付公開說明書','A 公司之發行新股應向主管機關申報生效後，始得為之','A 公司應至少提撥發行新股總額之百分之十五對外公開發行',null,'證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('107-4301-042','107-4301',42,'single_choice',2,'甲為A 上市公司之總經理，其知悉公司重大未公開的利空消息。於該消息未公開前之下列行為，何 者未違反證券交易法內線交易之規定？','甲自集中交易市場賣出該公司之普通公司債','甲自集中交易市場賣出A 公司股票','甲將該消息告知其好友乙，乙於消息未公開前賣出A 公司股票','甲原本要買A 公司股票，知悉該利空消息後就不買了',null,'證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('107-4301-043','107-4301',43,'single_choice',2,'A 公開發行公司募集發行新股，向認購投資人所交付之公開說明書主要內容有虛偽不實之情事。甲 認購後因而受有損害。依證券交易法之規定，下列敘述何者正確？','發行人如能證明已盡相當之注意，並有正當理由確信其主要內容無虛偽、隱匿情事或對於簽證之 意見有正當理由確信其為真實者，免負賠償責任','會計師如能證明已經合理調查，並有正當理由確信其簽證或意見為真實者，免負賠償責任','負責人因其過失致損害之發生者，應依其責任比例，負賠償責任','甲之損害賠償請求權，自其知有得受賠償之原因時起1 年間不行使而消滅；自募集、發行或買賣 之日起逾2 年者亦同',null,'證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('107-4301-044','107-4301',44,'single_choice',2,'甲初次擔任上市公司之董事，其聽說證券交易法有規定，董事對於上市公司所發行之某些有價證券， 若於取得後6 個月內再行賣出，或於賣出後6 個月內再行買進，因而獲得利益者，公司應請求將其 利益歸於公司。但也有些有價證券並無此一規定之適用。甲想請教您，下列何種有價證券無此一規 定之適用？','普通公司債','附認股權公司債','認股權憑證','臺灣存託憑證',null,'證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('107-4301-045','107-4301',45,'single_choice',2,'A 上市公司因股價表現不佳，該公司董事長甲為拉抬公司股價並製造股票交易活絡的假象，乃與其 好友乙以約定價格於甲出售A 公司股票時，乙同時為購買之相對行為。試問甲之行為成立證券交易 法之何刑責？','證券交易法第157 條之1 所定之內線交易','證券交易法第157 條所定之短線交易','證券交易法第155 條第1 項第5 款所定之沖洗買賣','證券交易法第155 條第1 項第3 款所定之相對委託',null,'證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('107-4301-046','107-4301',46,'single_choice',2,'甲依買賣關係起訴請求乙交付A 車，訴訟進行中，乙將A 車交付其員工丙，嗣後法院判決乙應交付 A 車予甲而告確定。甲發覺丙占有A 車，於是持該確定判決聲請對丙強制執行交付A 車。下列敘述， 何者錯誤？','丙承認依乙指示保管A 車時，執行法院得將A 車取交甲','丙雖然是判決以外之第三人，但執行法院對其執行時，亦得於執行程序終結前，對甲提起債務人 異議之訴','執行法院認丙非判決效力所及之人而裁定駁回甲之強制執行聲請時，甲得於裁定送達後10 日內對 丙提起許可執行之訴','丙如提起異議之訴，執行法院為避免丙受損害無法回復，得依職權命丙供擔保後停止執行',null,'強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('107-4301-047','107-4301',47,'single_choice',2,'債權人甲持臺灣臺北地方法院於民國106 年12 月1 日核發，准許甲收取債務人乙對丙之借款債權之收 取命令為執行名義，向臺灣士林地方法院（下稱士林地院）聲請對丙為強制執行，經士林地院囑託臺 灣臺中地方法院（下稱臺中地院）執行丙所有坐落於臺中市西正區之A 地。下列敘述，何者正確？','臺中地院得對甲之收取命令是否有效成立加以審查，如認其並未有效成立，應函覆士林地院無從執行','臺中地院得對甲之收取命令是否有效成立加以審查，如認其並未有效成立，應裁定駁回甲之強制 執行聲請','臺中地院對甲之收取命令是否有效成立加以審查，雖認其並未有效成立，但經詢問甲之意見後， 如甲堅持實施強制執行，仍應對丙實施強制執行','臺中地院對甲取得之執行名義是否有效成立不得加以審查，應受士林地院囑託逕行實施強制執行',null,'強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('107-4301-048','107-4301',48,'single_choice',2,'甲執給付金錢之確定判決為執行名義，聲請法院強制執行乙所飼養之A 牛，經查封之A 牛已懷孕， 預定於2 個月後生產。下列敘述，何者正確？','查封之效力及於A 牛2 個月後生產之小牛','A 牛必須於生產後始得拍賣','未經甲同意，不得以乙為A 牛之保管人','乙於A 牛被查封後，將其出賣給丙，乙、丙間之買賣契約為無效',null,'強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('107-4301-049','107-4301',49,'single_choice',2,'債權人甲持對債務人乙之勝訴確定判決聲請執行乙所有之A 地，經執行法院定於民國106 年11 月1 日下午4 時以投標方式舉行第一次公開拍賣，底價定為新臺幣（下同）100 萬元，保證金定為20 萬 元並命於投標前繳納保證金。下列敘述，何者錯誤？','乙不得參與投標應買A 地','第一次公開拍賣如無人應買，甲亦不願承受時，執行法院減價拍賣（第二次拍賣）所定之拍賣底 價得定為95 萬元','乙之其他普通債權人丙於106 年10 月30 日至執行法院提出確定判決正本，並以言詞向執行法院 聲明參與分配，經執行書記官記明筆錄者，發生聲明參與分配之效力','丁於開標前如未繳納保證金，應認其投標無效，不得補正',null,'強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('107-4301-050','107-4301',50,'single_choice',2,'金錢債權人甲、乙、丙同時聲請強制執行債務人丁所有之A 地，經執行法院就其拍賣所得價金作成 分配表。下列何者非屬得對分配表聲明異議之事由？','甲因法院以其所持本票裁定未合法送達丁為由，未將該本票債權列入分配表','乙以其債權為A 地抵押權所擔保範圍，法院未將之列入優先順位','丙以乙之債權不存在，法院應將乙之受分配額剔除','丁以丙之執行債權已罹於消滅時效，法院應將丙之受分配額剔除',null,'強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('107-4301-051','107-4301',51,'single_choice',2,'甲以每月新臺幣（下同）1 萬元租金向乙承租A 屋，雙方簽訂2 年之定期租賃契約。乙在出租前曾 向丙銀行借款200 萬元，同時以該屋設定抵押權予以擔保。在租賃期間內，丙銀行因乙未如期清償 本息，取得拍賣抵押物裁定後，向執行法院聲請拍賣A 屋。下列敘述，何者錯誤？','如A 屋定底價200 萬元拍賣，因存有定期租賃契約而無人應買，丙銀行得聲請執行法院除去甲之 租賃權後再行拍賣','如未除去甲之租賃權而拍賣A 屋，拍定人丁不繼受甲、乙間之租賃關係','如經執行法院除去甲之租賃權而拍賣A 屋，拍定人丁得向執行法院聲請點交，解除甲之占有','甲就A 屋之拍賣並無優先承買權',null,'強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('107-4301-052','107-4301',52,'single_choice',2,'甲、乙、丙共有A 地，應有部分各1/3，甲以乙、丙為被告訴請法院裁判分割該地。下列敘述，何者 正確？','法院判決變價分割確定，僅甲得向執行法院聲請強制執行','法院判決變價分割確定，於變價分割之執行程序，甲、乙分別聲明願優先承買時，應由甲、乙按 應有部分比例共同優先承買，即由甲、乙各優先承買A 地應有部分1/2','法院判決原物分割確定，乙、丙不願意配合甲為分割登記時，甲得向執行法院聲請強制執行，由 執行法院對乙、丙發協同辦理分割登記之自動履行命令','法院判決原物分割確定，甲所分得部分為丙占有時，甲得以該判決為執行名義，聲請執行法院排 除丙之占有',null,'強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('107-4301-053','107-4301',53,'single_choice',2,'甲、乙經法院判決離婚確定，法院於同一判決並酌定兩人所生未成年子女丙權利義務之行使、負擔 由乙任之，但甲得依一定方式與丙會面交往。關於前開裁判之強制執行，下列敘述，何者錯誤？','如判決後丙仍與甲同住，乙向法院聲請命甲交出丙之強制執行時，法院得直接將丙取交於乙','如判決後丙與乙同住，甲就裁判所定會面交往聲請強制執行時，乙所負者為協力義務，法院僅得 採間接強制方式對乙執行','執行法院就前述交付子女或會面交往之強制執行，於必要時得發函內政部移民署，限制丙非經甲、 乙之同意，不得出國','如甲、乙任一方已攜丙出國，我國法院無法囑託外國法院代為執行',null,'強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('107-4301-054','107-4301',54,'single_choice',2,'臺中市政府為拓寬道路工程而徵收乙所有坐落於臺中市之A 地及其上之B 屋，定期於民國106 年12 月12 日上午8 時依法拆除B 屋，乙認為臺中市政府之徵收行為無效，遂於106 年12 月1 日具狀向 臺灣臺中地方法院（下稱臺中地院）聲請對臺中市政府為假處分，禁止臺中市政府之拆遷行為。下 列敘述，何者正確？','如乙已釋明假處分之請求及假處分之原因，臺中地院即應裁定准許乙假處分之聲請','臺中地院准許乙假處分之聲請後，亦得隨時依臺中市政府之聲請供擔保而撤銷該假處分','系爭房地之徵收處分是否無效之爭議，屬公法上之爭議，但乙為保全B 屋所有權而聲請假處分， 臺中地院仍可加以審認決定是否准許','臺中地院應否准乙假處分之聲請',null,'強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('107-4301-055','107-4301',55,'single_choice',2,'債權人甲持禁止債務人乙處分A 地之假處分裁定，向執行法院聲請執行後，乙之另一債權人丙持假 扣押裁定，向執行法院聲請查封該地。執行法院應如何處置？','依丙之聲請查封A 地','駁回丙之假扣押執行聲請','將丙之假扣押執行併入甲之假處分執行','撤銷甲之假處分執行',null,'強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
